import { useState } from 'react';
import {
  JxAlert,
  JxButton,
  JxInputField,
  JxSelect,
  JxSwitch,
  JxToast,
} from '@jinx-ui/react';

const EMAIL_RE = /^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/;

const ROLES = [
  { value: 'viewer', label: 'Наблюдатель', meta: 'только чтение' },
  { value: 'editor', label: 'Редактор' },
  { value: 'admin', label: 'Администратор' },
];

export default function TeamInviteForm() {
  const [email, setEmail] = useState('');
  const [touched, setTouched] = useState(false);
  const [role, setRole] = useState('editor');
  const [notify, setNotify] = useState(true);
  const [sent, setSent] = useState<{ email: string; role: string } | null>(null);

  const valid = EMAIL_RE.test(email.trim());

  const submit = (event: React.FormEvent<HTMLFormElement>) => {
    event.preventDefault();
    if (!valid) {
      setTouched(true);
      return;
    }
    const roleLabel = ROLES.find((item) => item.value === role)?.label ?? role;
    setSent({ email: email.trim(), role: roleLabel });
    setEmail('');
    setTouched(false);
  };

  return (
    <div style={{ display: 'grid', gap: '16px', maxWidth: '420px' }}>
      {sent ? (
        <JxToast
          variant="success"
          title="Приглашение отправлено"
          message={`${sent.email} — роль «${sent.role}»${notify ? ', уведомление ушло на почту' : ''}`}
          onClose={() => setSent(null)}
        />
      ) : null}

      <form onSubmit={submit} style={{ display: 'grid', gap: '16px' }}>
        <JxInputField
          label="Электронная почта"
          type="email"
          required
          placeholder="name@company.com"
          value={email}
          onChange={(event) => setEmail(event.target.value)}
          onBlur={() => setTouched(true)}
          helperText="Приглашение придёт на этот адрес"
          errorText={touched && !valid ? 'Похоже, это не адрес почты' : undefined}
        />

        <JxSelect
          label="Роль в команде"
          options={ROLES}
          value={role}
          onValueChange={setRole}
        />

        <JxSwitch
          label="Отправить уведомление"
          checked={notify}
          onChange={(event) => setNotify(event.target.checked)}
        />

        <JxButton type="submit" variant="primary" disabled={!valid}>
          Отправить приглашение
        </JxButton>

        {!valid && touched ? (
          <JxAlert intent="info" title="Проверьте адрес">
            Кнопка станет активной, когда почта будет введена целиком.
          </JxAlert>
        ) : null}
      </form>
    </div>
  );
}

